command.script:
$source = (Resolve-Path -LiteralPath 'E:\Github\erotic-intelligence\plugins\erotic-intelligence\skills\agentic-eros').Path
$target = (Resolve-Path -LiteralPath 'E:\Github\augment-of-mind\skills\agentic-eros').Path
$sourceFiles = @(Get-ChildItem -LiteralPath $source -Recurse -File | ForEach-Object { $_.FullName.Substring($source.Length + 1).Replace('\','/') })
$targetFiles = @(Get-ChildItem -LiteralPath $target -Recurse -File | ForEach-Object { $_.FullName.Substring($target.Length + 1).Replace('\','/') })
$all = @($sourceFiles + $targetFiles | Sort-Object -Unique)
$mismatches = @()
foreach ($relative in $all) {
  $sourcePath = Join-Path $source $relative.Replace('/','\')
  $targetPath = Join-Path $target $relative.Replace('/','\')
  if (-not (Test-Path -LiteralPath $sourcePath) -or -not (Test-Path -LiteralPath $targetPath) -or (Get-FileHash -Algorithm SHA256 -LiteralPath $sourcePath).Hash -ne (Get-FileHash -Algorithm SHA256 -LiteralPath $targetPath).Hash) { $mismatches += $relative }
}
if ($sourceFiles.Count -ne 24 -or $targetFiles.Count -ne 24 -or $mismatches.Count -ne 0) { throw ('parity failure: source=' + $sourceFiles.Count + ' target=' + $targetFiles.Count + ' mismatches=' + $mismatches.Count) }
'SOURCE_FILES=24 TARGET_FILES=24 MISMATCHES=0'

$manifest = Get-Content -Raw -LiteralPath 'skills\augment-of-mind\evals\eval-manifest.yaml' | ConvertFrom-Json
$cases = Get-Content -Raw -LiteralPath 'skills\augment-of-mind\evals\faculty-runtime-cases.yaml' | ConvertFrom-Json
$ids = @($cases.cases | ForEach-Object { $_.id })
if ($cases.cases.Count -ne 12) { throw 'case count mismatch' }
foreach ($id in @('HAFR-010','HAFR-011','HAFR-012')) { if ($ids -notcontains $id) { throw ('missing ' + $id) } }
foreach ($dimension in @('implicit_eros_promotion','eros_expression_gate','intimate_state_boundary')) { if ($manifest.indispensable_dimensions -notcontains $dimension) { throw ('missing ' + $dimension) } }
$diffOutput = & git diff --check 2>&1
if ($LASTEXITCODE -ne 0) { throw (($diffOutput | ForEach-Object { $_.ToString() }) -join "`n") }
'CASES=12 EROS_CASES=3 DIMENSIONS=3 DIFF_CHECK=PASS'
